2|name: threejs-animation
3|description: Three.js animation - keyframe animation, skeletal animation, morph targets, animation mixing. Use when animating objects, playing GLTF animations, creating procedural motion, or blending animations.
4|---
5|
6|# Three.js Animation
7|
8|## Quick Start
9|
10|```javascript
11|import * as THREE from "three";
12|
13|// Simple procedural animation
14|const clock = new THREE.Clock();
15|
16|function animate() {
17|  const delta = clock.getDelta();
18|  const elapsed = clock.getElapsedTime();
19|
20|  mesh.rotation.y += delta;
21|  mesh.position.y = Math.sin(elapsed) * 0.5;
22|
23|  requestAnimationFrame(animate);
24|  renderer.render(scene, camera);
25|}
26|animate();
27|```
28|
29|## Animation System Overview
30|
31|Three.js animation system has three main components:
32|
33|1. **AnimationClip** - Container for keyframe data
34|2. **AnimationMixer** - Plays animations on a root object
35|3. **AnimationAction** - Controls playback of a clip
36|
37|## AnimationClip
38|
39|Stores keyframe animation data.
40|
41|```javascript
42|// Create animation clip
43|const times = [0, 1, 2]; // Keyframe times (seconds)
44|const values = [0, 1, 0]; // Values at each keyframe
45|
46|const track = new THREE.NumberKeyframeTrack(
47|  ".position[y]", // Property path
48|  times,
49|  values,
50|);
51|
52|const clip = new THREE.AnimationClip("bounce", 2, [track]);
53|```
54|
55|### KeyframeTrack Types
56|
57|```javascript
58|// Number track (single value)
59|new THREE.NumberKeyframeTrack(".opacity", times, [1, 0]);
60|new THREE.NumberKeyframeTrack(".material.opacity", times, [1, 0]);
61|
62|// Vector track (position, scale)
63|new THREE.VectorKeyframeTrack(".position", times, [
64|  0,
65|  0,
66|  0, // t=0
67|  1,
68|  2,
69|  0, // t=1
70|  0,
71|  0,
72|  0, // t=2
73|]);
74|
75|// Quaternion track (rotation)
76|const q1 = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, 0, 0));
77|const q2 = new THREE.Quaternion().setFromEuler(new THREE.Euler(0, Math.PI, 0));
78|new THREE.QuaternionKeyframeTrack(
79|  ".quaternion",
80|  [0, 1],
81|  [q1.x, q1.y, q1.z, q1.w, q2.x, q2.y, q2.z, q2.w],
82|);
83|
84|// Color track
85|new THREE.ColorKeyframeTrack(".material.color", times, [
86|  1,
87|  0,
88|  0, // red
89|  0,
90|  1,
91|  0, // green
92|  0,
93|  0,
94|  1, // blue
95|]);
96|
97|// Boolean track
98|new THREE.BooleanKeyframeTrack(".visible", [0, 0.5, 1], [true, false, true]);
99|
100|// String track (for morph targets)
101|new THREE.StringKeyframeTrack(
102|  ".morphTargetInfluences[smile]",
103|  [0, 1],
104|  ["0", "1"],
105|);
106|```
107|
108|### Interpolation Modes
109|
110|```javascript
111|const track = new THREE.VectorKeyframeTrack(".position", times, values);
112|
113|// Interpolation
114|track.setInterpolation(THREE.InterpolateLinear); // Default
115|track.setInterpolation(THREE.InterpolateSmooth); // Cubic spline
116|track.setInterpolation(THREE.InterpolateDiscrete); // Step function
117|```
118|
119|## AnimationMixer
120|
121|Plays animations on an object and its descendants.
122|
123|```javascript
124|const mixer = new THREE.AnimationMixer(model);
125|
126|// Create action from clip
127|const action = mixer.clipAction(clip);
128|action.play();
129|
130|// Update in animation loop
131|function animate() {
132|  const delta = clock.getDelta();
133|  mixer.update(delta); // Required!
134|
135|  requestAnimationFrame(animate);
136|  renderer.render(scene, camera);
137|}
138|```
139|
140|### Mixer Events
141|
142|```javascript
143|mixer.addEventListener("finished", (e) => {
144|  console.log("Animation finished:", e.action.getClip().name);
145|});
146|
147|mixer.addEventListener("loop", (e) => {
148|  console.log("Animation looped:", e.action.getClip().name);
149|});
150|```
151|
152|## AnimationAction
153|
154|Controls playback of an animation clip.
155|
156|```javascript
157|const action = mixer.clipAction(clip);
158|
159|// Playback control
160|action.play();
161|action.stop();
162|action.reset();
163|action.halt(fadeOutDuration);
164|
165|// Playback state
166|action.isRunning();
167|action.isScheduled();
168|
169|// Time control
170|action.time = 0.5; // Current time
171|action.timeScale = 1; // Playback speed (negative = reverse)
172|action.paused = false;
173|
174|// Weight (for blending)
175|action.weight = 1; // 0-1, contribution to final pose
176|action.setEffectiveWeight(1);
177|
178|// Loop modes
179|action.loop = THREE.LoopRepeat; // Default: loop forever
180|action.loop = THREE.LoopOnce; // Play once and stop
181|action.loop = THREE.LoopPingPong; // Alternate forward/backward
182|action.repetitions = 3; // Number of loops (Infinity default)
183|
184|// Clamping
185|action.clampWhenFinished = true; // Hold last frame when done
186|
187|// Blending
188|action.blendMode = THREE.NormalAnimationBlendMode;
189|action.blendMode = THREE.AdditiveAnimationBlendMode;
190|```
191|
192|### Fade In/Out
193|
194|```javascript
195|// Fade in
196|action.reset().fadeIn(0.5).play();
197|
198|// Fade out
199|action.fadeOut(0.5);
200|
201|// Crossfade between animations
202|const action1 = mixer.clipAction(clip1);
203|const action2 = mixer.clipAction(clip2);
204|
205|action1.play();
206|
207|// Later, crossfade to action2
208|action1.crossFadeTo(action2, 0.5, true);
209|action2.play();
210|```
211|
212|## Loading GLTF Animations
213|
214|Most common source of skeletal animations.
215|
216|```javascript
217|import { GLTFLoader } from "three/examples/jsm/loaders/GLTFLoader.js";
218|
219|const loader = new GLTFLoader();
220|loader.load("model.glb", (gltf) => {
221|  const model = gltf.scene;
222|  scene.add(model);
223|
224|  // Create mixer
225|  const mixer = new THREE.AnimationMixer(model);
226|
227|  // Get all clips
228|  const clips = gltf.animations;
229|  console.log(
230|    "Available animations:",
231|    clips.map((c) => c.name),
232|  );
233|
234|  // Play first animation
235|  if (clips.length > 0) {
236|    const action = mixer.clipAction(clips[0]);
237|    action.play();
238|  }
239|
240|  // Play specific animation by name
241|  const walkClip = THREE.AnimationClip.findByName(clips, "Walk");
242|  if (walkClip) {
243|    mixer.clipAction(walkClip).play();
244|  }
245|
246|  // Store mixer for update loop
247|  window.mixer = mixer;
248|});
249|
250|// Animation loop
251|function animate() {
252|  const delta = clock.getDelta();
253|  if (window.mixer) window.mixer.update(delta);
254|
255|  requestAnimationFrame(animate);
256|  renderer.render(scene, camera);
257|}
258|```
259|
260|## Skeletal Animation
261|
262|### Skeleton and Bones
263|
264|```javascript
265|// Access skeleton from skinned mesh
266|const skinnedMesh = model.getObjectByProperty("type", "SkinnedMesh");
267|const skeleton = skinnedMesh.skeleton;
268|
269|// Access bones
270|skeleton.bones.forEach((bone) => {
271|  console.log(bone.name, bone.position, bone.rotation);
272|});
273|
274|// Find specific bone by name
275|const headBone = skeleton.bones.find((b) => b.name === "Head");
