/* The Surfing Pelican — full-screen, non-interactive stage.
   All overlay text is pointer-events: none; there is nothing to click. */

:root {
  --ink: #ffffff;
  --ink-soft: rgba(255, 255, 255, 0.86);
  --shadow: rgba(4, 42, 56, 0.45);
}

* { box-sizing: border-box; }

html, body {
  margin: 0;
  height: 100%;
  overflow: hidden;
  background: #79c4e2;
}

body {
  font-family: "Gill Sans", "Trebuchet MS", "Segoe UI", system-ui, sans-serif;
  color: var(--ink);
}

#scene {
  position: fixed;
  inset: 0;
  width: 100%;
  height: 100%;
  display: block;
}

.vignette {
  position: fixed;
  inset: 0;
  pointer-events: none;
  background:
    radial-gradient(ellipse 120% 90% at 50% 42%, transparent 58%, rgba(5, 45, 62, 0.28) 100%),
    linear-gradient(to top, rgba(4, 42, 56, 0.30), transparent 32%);
}

.badge {
  position: fixed;
  top: 20px;
  left: 22px;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 8px 14px 9px;
  border-radius: 999px;
  background: rgba(6, 52, 68, 0.42);
  color: var(--ink-soft);
  font-size: 13.5px;
  letter-spacing: 0.01em;
  pointer-events: none;
}

.badge-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #ffd166;
  box-shadow: 0 0 0 0 rgba(255, 209, 102, 0.55);
  animation: pulse 2.6s ease-in-out infinite;
}

@keyframes pulse {
  0%   { box-shadow: 0 0 0 0 rgba(255, 209, 102, 0.55); }
  70%  { box-shadow: 0 0 0 9px rgba(255, 209, 102, 0); }
  100% { box-shadow: 0 0 0 0 rgba(255, 209, 102, 0); }
}

.caption {
  position: fixed;
  left: 24px;
  bottom: 26px;
  max-width: 430px;
  pointer-events: none;
  text-shadow: 0 1px 14px var(--shadow), 0 1px 3px var(--shadow);
}

.caption h1 {
  margin: 0 0 8px;
  font-family: "Iowan Old Style", Palatino, "Palatino Linotype", Georgia, serif;
  font-size: clamp(34px, 5.2vw, 58px);
  font-weight: 600;
  line-height: 1.02;
  letter-spacing: -0.01em;
}

.caption p {
  margin: 0;
  font-size: clamp(14px, 1.6vw, 16.5px);
  line-height: 1.55;
  color: var(--ink-soft);
}

.credit {
  position: fixed;
  right: 22px;
  bottom: 24px;
  font-size: 12.5px;
  color: rgba(255, 255, 255, 0.72);
  text-shadow: 0 1px 8px var(--shadow);
  pointer-events: none;
}

.fallback {
  position: fixed;
  inset: 0;
  display: grid;
  place-items: center;
  padding: 24px;
  background: #0e6f96;
  text-align: center;
  font-size: 16px;
  line-height: 1.6;
}

.fallback[hidden] { display: none; }

@media (max-width: 640px) {
  .badge { top: 14px; left: 14px; font-size: 12.5px; }
  .caption { left: 16px; right: 16px; bottom: 44px; }
  .credit { right: 16px; bottom: 16px; }
}

@media (prefers-reduced-motion: reduce) {
  .badge-dot { animation: none; }
}

// The Surfing Pelican — a non-interactive Three.js loop.
// Everything is procedural: the pelican, surfboard, curling wave, ocean,
// spray, clouds, islands and gulls are all built and animated in code.
// There are deliberately no controls — the camera drifts on its own.

import * as THREE from "three";

const canvas = document.getElementById("scene");
const fallback = document.getElementById("fallback");
const reducedMotion = window.matchMedia("(prefers-reduced-motion: reduce)").matches;
const MOTION = reducedMotion ? 0.3 : 1; // gentler motion when requested

let renderer;
try {
  renderer = new THREE.WebGLRenderer({ canvas, antialias: true, powerPreference: "high-performance" });
} catch (err) {
  fallback.hidden = false;
  throw err;
}
renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
renderer.setSize(window.innerWidth, window.innerHeight);
renderer.shadowMap.enabled = true;
renderer.shadowMap.type = THREE.PCFSoftShadowMap;
renderer.toneMapping = THREE.ACESFilmicToneMapping;
renderer.toneMappingExposure = 1.12;
renderer.outputColorSpace = THREE.SRGBColorSpace;

const scene = new THREE.Scene();
scene.fog = new THREE.Fog(0xd6f0f7, 34, 92);

const camera = new THREE.PerspectiveCamera(42, window.innerWidth / window.innerHeight, 0.1, 220);
camera.position.set(7.5, 5.4, 14);

// ---------- helpers ----------

function softDotTexture(size = 64) {
  const c = document.createElement("canvas");
  c.width = c.height = size;
  const ctx = c.getContext("2d");
  const g = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
  g.addColorStop(0, "rgba(255,255,255,1)");
  g.addColorStop(0.45, "rgba(255,255,255,0.85)");
  g.addColorStop(1, "rgba(255,255,255,0)");
  ctx.fillStyle = g;
  ctx.fillRect(0, 0, size, size);
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  return tex;
}

function boardTexture() {
  const c = document.createElement("canvas");
  c.width = 1024; c.height = 288;
  const ctx = c.getContext("2d");
  ctx.fillStyle = "#ff6b4a"; // coral deck
  ctx.fillRect(0, 0, c.width, c.height);
  ctx.fillStyle = "#2a9db4"; // teal rails
  ctx.fillRect(0, 0, c.width, 26);
  ctx.fillRect(0, c.height - 26, c.width, 26);
  ctx.fillStyle = "#fff3d6"; // cream centre stripe
  ctx.fillRect(0, c.height / 2 - 34, c.width, 68);
  ctx.fillStyle = "#ffb703"; // gold pinstripes
  ctx.fillRect(0, c.height / 2 - 52, c.width, 10);
  ctx.fillRect(0, c.height / 2 + 42, c.width, 10);
  // little wave logo near the nose
  ctx.strokeStyle = "#0b6e8c";
  ctx.lineWidth = 9;
  ctx.lineCap = "round";
  ctx.beginPath();
  ctx.arc(880, c.height / 2, 40, Math.PI * 0.15, Math.PI * 1.55);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(848, c.height / 2 + 26);
  ctx.quadraticCurveTo(880, c.height / 2 - 6, 912, c.height / 2 + 26);
  ctx.stroke();
  const tex = new THREE.CanvasTexture(c);
  tex.colorSpace = THREE.SRGBColorSpace;
  tex.anisotropy = 8;
  // ExtrudeGeometry cap UVs are the shape xy coordinates, so map the
  // shape bounding box [-1.78..1.78] x [-0.5..0.5] into 0..1.
  tex.repeat.set(1 / 3.56, 1 / 1.0);
  tex.offset.set(0.5, 0.5);
  return tex;
}

const rand = (a, b) => a + Math.random() * (b - a);
const clamp = THREE.MathUtils.clamp;

// ---------- sky, sun, lights ----------

const skyMat = new THREE.ShaderMaterial({
  side: THREE.BackSide,
  depthWrite: false,
  fog: false,
  uniforms: {
    top: { value: new THREE.Color(0x3f9fd6) },
    mid: { value: new THREE.Color(0x8fd0ec) },
    horizon: { value: new THREE.Color(0xffeec2) },
  },
  vertexShader: `
    varying vec3 vPos;
    void main() {
      vPos = position;
      gl_Position = projectionMatrix * modelViewMatrix * vec4(position, 1.0);
    }`,
  fragmentShader: `
    uniform vec3 top; uniform vec3 mid; uniform vec3 horizon;
    varying vec3 vPos;
    void main() {
      float h = normalize(vPos).y;
      vec3 col = mix(horizon, mid, smoothstep(-0.02, 0.22, h));
      col = mix(col, top, smoothstep(0.18, 0.65, h));
      col = mix(vec3(0.16, 0.55, 0.68), col, smoothstep(-0.25, 0.0, h));
      gl_FragColor = vec4(col, 1.0);
    }`,
});
scene.add(new THREE.Mesh(new THREE.SphereGeometry(110, 32, 20), skyMat));

const sunPos = new THREE.Vector3(-26, 22, -42);
const sunGlow = new THREE.Sprite(new THREE.SpriteMaterial({
  map: softDotTexture(128), color: 0xffe9a8, transparent: true, opacity: 0.95, fog: false, depthWrite: false,
