// ---------- drifting clouds, islands, gulls ----------

const clouds = [];
{
  const mat = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 1 });
  const puff = new THREE.SphereGeometry(1, 12, 10);
  for (let i = 0; i < 6; i++) {
    const cloud = new THREE.Group();
    const blobs = 4 + Math.floor(Math.random() * 3);
    for (let b = 0; b < blobs; b++) {
      const m = new THREE.Mesh(puff, mat);
      m.position.set(b * rand(0.9, 1.3) - blobs * 0.55, rand(-0.2, 0.35), rand(-0.4, 0.4));
      m.scale.set(rand(1.0, 1.9), rand(0.5, 0.75), rand(0.8, 1.2));
      cloud.add(m);
    }
    cloud.position.set(rand(-42, 42), rand(11, 18), rand(-38, -24));
    cloud.scale.setScalar(rand(1.1, 2.0));
    cloud.userData.speed = rand(0.25, 0.6);
    scene.add(cloud);
    clouds.push(cloud);
  }
}

function makePalm(height = 2.6) {
  const palm = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8a6a48, roughness: 0.9 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x2e9e5b, roughness: 0.8, side: THREE.DoubleSide });
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(0.25, height * 0.6, 0), new THREE.Vector3(0.65, height, 0)
  );
  palm.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 8, 0.09, 6), trunkMat));
  const top = curve.getPoint(1);
  for (let i = 0; i < 7; i++) {
    const frond = new THREE.Mesh(new THREE.ConeGeometry(0.16, 1.7, 5), leafMat);
    const holder = new THREE.Group();
    holder.position.copy(top);
    holder.rotation.y = (i / 7) * Math.PI * 2;
    frond.position.set(0.8, 0.18, 0);
    frond.rotation.z = -Math.PI / 2 + 0.55; // arc outward and droop
    frond.scale.set(1, 1, 0.35);
    holder.add(frond);
    palm.add(holder);
  }
  return palm;
}

{
  const sandMat = new THREE.MeshStandardMaterial({ color: 0xf2d99a, roughness: 1 });
  const greenMat = new THREE.MeshStandardMaterial({ color: 0x35a06f, roughness: 1 });
  const islandAt = (x, z, s, palms) => {
    const g = new THREE.Group();
    const sand = new THREE.Mesh(new THREE.CylinderGeometry(3.4, 4.1, 0.7, 20), sandMat);
    sand.position.y = -0.25;
    g.add(sand);
    const hill = new THREE.Mesh(new THREE.SphereGeometry(2.5, 16, 12), greenMat);
    hill.scale.set(1, 0.42, 1);
    hill.position.y = 0.15;
    g.add(hill);
    for (let i = 0; i < palms; i++) {
      const p = makePalm(rand(2.2, 3.2));
      p.position.set(rand(-1.6, 1.6), 0.7, rand(-1.2, 1.2));
      p.rotation.y = rand(0, 6.28);
      g.add(p);
    }
    g.position.set(x, 0, z);
    g.scale.setScalar(s);
    scene.add(g);
  };
  islandAt(-26, -30, 1.15, 3);
  islandAt(28, -34, 0.9, 2);
  islandAt(14, -44, 1.5, 2);
}

const gulls = [];
{
  const white = new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.8, side: THREE.DoubleSide });
  const tip = new THREE.MeshStandardMaterial({ color: 0x3a4248, roughness: 0.8, side: THREE.DoubleSide });
  for (let i = 0; i < 4; i++) {
    const gull = new THREE.Group();
    const body = new THREE.Mesh(new THREE.CapsuleGeometry(0.13, 0.5, 4, 8), white);
    body.rotation.x = Math.PI / 2;
    gull.add(body);
    const wings = [];
    for (const side of [-1, 1]) {
      const pivot = new THREE.Group();
      const w = new THREE.Mesh(new THREE.BoxGeometry(1.05, 0.035, 0.3), white);
      w.position.x = side * 0.55;
      const t = new THREE.Mesh(new THREE.BoxGeometry(0.3, 0.035, 0.24), tip);
      t.position.x = side * 1.2;
      pivot.add(w, t);
      gull.add(pivot);
      wings.push({ pivot, side });
    }
    gull.userData = {
      wings, radius: rand(16, 30), height: rand(11, 17),
      speed: rand(0.05, 0.1) * (Math.random() < 0.5 ? 1 : -1),
      phase: rand(0, 6.28), flap: rand(5, 7.5),
    };
    scene.add(gull);
    gulls.push(gull);
  }
}

function updateSkyLife(T, dt) {
  for (const c of clouds) {
    c.position.x += c.userData.speed * dt * (0.3 + 0.7 * MOTION);
    if (c.position.x > 52) c.position.x = -52;
  }
  for (const g of gulls) {
    const u = g.userData;
    const a = u.phase + T * u.speed * (0.3 + 0.7 * MOTION);
    const x = Math.cos(a) * u.radius, z = -26 + Math.sin(a) * u.radius * 0.35;
    g.position.set(x, u.height + Math.sin(T * 0.7 + u.phase) * 0.6, z);
    g.rotation.y = -a + (u.speed > 0 ? 0 : Math.PI);
    const flap = Math.sin(T * u.flap * (0.4 + 0.6 * MOTION) + u.phase) * 0.55;
    for (const w of u.wings) w.pivot.rotation.z = w.side * flap * 0.7 + flap * 0.3 * w.side;
  }
}

