+
+const lookTarget = new THREE.Vector3(0, 3.4, 0);
+const desiredCam = new THREE.Vector3();
+const desiredLook = new THREE.Vector3();
+
+function updateCamera(T, dt, riderX) {
+  const aspect = camera.aspect;
+  const dist = aspect < 0.85 ? 1.5 : aspect < 1.25 ? 1.22 : 1.0;
+  desiredCam.set(
+    4.4 + riderX * 0.3 + Math.sin(T * 0.12) * 1.7 * MOTION,
+    5.1 + Math.sin(T * 0.19) * 0.55 * MOTION,
+    13.6 * dist + Math.sin(T * 0.09) * 0.9 * MOTION
+  );
+  desiredLook.set(riderX * 0.55, 3.35 + Math.sin(T * 0.23) * 0.2 * MOTION, 0.2);
+  const k = 1 - Math.exp(-dt * 2.2);
+  camera.position.lerp(desiredCam, k);
+  lookTarget.lerp(desiredLook, k);
+  camera.lookAt(lookTarget);
+}
+
+// ---------- main loop ----------
+
+window.addEventListener("resize", () => {
+  camera.aspect = window.innerWidth / window.innerHeight;
+  camera.updateProjectionMatrix();
+  renderer.setSize(window.innerWidth, window.innerHeight);
+  renderer.setPixelRatio(Math.min(window.devicePixelRatio, 2));
+});
+
+const clock = new THREE.Clock();
+
+function animate() {
+  requestAnimationFrame(animate);
+  const dt = Math.min(clock.getDelta(), 0.05);
+  const T = clock.elapsedTime;
+
+  const { x, intensity } = updateRider(T);
+  updateWave(T);
+  updateOcean(T);
+  updateStreaks(dt);
+  emitParticles(dt, x, intensity);
+  updateParticles(boardSpray, dt, 6.5);
+  updateParticles(lipMist, dt, 0.35);
+  sparkleMat.opacity = 0.35 + 0.25 * (0.5 + 0.5 * Math.sin(T * 2.7));
+  updateSkyLife(T, dt);
+  updateCamera(T, dt, x);
+
+  renderer.render(scene, camera);
+}
+animate();

