import * as THREE from "three";
const curve = new THREE.CatmullRomCurve3([
  new THREE.Vector3(0, -0.25, 6.4), new THREE.Vector3(0, 0.05, 4.6),
  new THREE.Vector3(0, 0.75, 2.9), new THREE.Vector3(0, 1.9, 1.55),
  new THREE.Vector3(0, 3.05, 0.55), new THREE.Vector3(0, 4.15, -0.25),
  new THREE.Vector3(0, 5.15, -0.75), new THREE.Vector3(0, 6.05, -0.55),
  new THREE.Vector3(0, 6.8, 0.45), new THREE.Vector3(0, 7.0, 1.75),
  new THREE.Vector3(0, 6.55, 2.55), new THREE.Vector3(0, 5.5, 2.35),
  new THREE.Vector3(0, 4.6, 1.6),
], false, "centripetal");
const pts = curve.getSpacedPoints(220);
let maxY = { t: 0, y: -1, z: 0 }, maxFwdUpper = { t: 0, y: 0, z: -99 };
pts.forEach((p, i) => {
  const t = i / (pts.length - 1);
  if (p.y > maxY.y) maxY = { t, y: p.y, z: p.z };
  if (p.y > 5.5 && p.z > maxFwdUpper.z) maxFwdUpper = { t, y: p.y, z: p.z };
});
console.log("maxY (crest):", JSON.stringify(maxY));
console.log("most-forward upper point (lip underside):", JSON.stringify(maxFwdUpper));
for (const t of [0.35, 0.425, 0.5, 0.74, 0.8, 0.84]) {
  const p = pts[Math.round(t * (pts.length - 1))];
  console.log(`t=${t}  y=${p.y.toFixed(2)} z=${p.z.toFixed(2)}  (scaled y at centre=${(p.y * 1.08).toFixed(2)})`);
}

