function makePalm(height = 2.6) {
  const palm = new THREE.Group();
  const trunkMat = new THREE.MeshStandardMaterial({ color: 0x8a6a48, roughness: 0.9 });
  const leafMat = new THREE.MeshStandardMaterial({ color: 0x2e9e5b, roughness: 0.8, side: THREE.DoubleSide });
  const curve = new THREE.QuadraticBezierCurve3(
    new THREE.Vector3(0, 0, 0), new THREE.Vector3(0.25, height * 0.6, 0), new THREE.Vector3(0.65, height, 0)
  );
  palm.add(new THREE.Mesh(new THREE.TubeGeometry(curve, 8, 0.09, 6), trunkMat));
  const top = curve.getPoint(1);
  for (let i = 0; i < 7; i++) {
    const frond = new THREE.Mesh(new THREE.ConeGeometry(0.16, 1.7, 5), leafMat);
    const holder = new THREE.Group();
    holder.position.copy(top);
    holder.rotation.y = (i / 7) * Math.PI * 2;
    frond.position.set(0.8, 0.18, 0);
    frond.rotation.z = -Math.PI / 2 + 0.55; // arc outward and droop
    frond.scale.set(1, 1, 0.35);
    holder.add(frond);
    palm.add(holder);
  }
  return palm;
}

