// Foam: a churned lip line plus whitewater in the trough (one instanced mesh).
{
  const count = 240;
  const foam = new THREE.InstancedMesh(
    new THREE.SphereGeometry(1, 10, 8),
    new THREE.MeshStandardMaterial({ color: 0xffffff, roughness: 0.95 }),
    count
  );
  const dummy = new THREE.Object3D();
  for (let i = 0; i < count; i++) {
    const lip = i < 165;
    // Foam concentrates near the break at x = -2, thinning down the line;
    // whitewater likewise stays by the break, clear of the foreground.
    const x = lip
      ? (Math.random() < 0.75 ? rand(-11, 4.5) : rand(-13.5, 6))
      : rand(-12, 2);
    // t is arc length along the profile: the crest/lip tip sits near
    // t = 0.88, so foam hugs 0.82-0.905, clear of the lip underside.
    const t = lip ? rand(0.82, 0.905) : rand(0.09, 0.17);
    const p = wavePoint(x, t);
    dummy.position.set(x + rand(-0.14, 0.14), p.y + rand(-0.1, 0.06), p.z + rand(-0.14, 0.14));
    dummy.rotation.set(rand(0, 3), rand(0, 3), rand(0, 3));
    if (lip) dummy.scale.set(rand(0.16, 0.42), rand(0.08, 0.2), rand(0.16, 0.38));
    else dummy.scale.set(rand(0.22, 0.5), rand(0.05, 0.1), rand(0.2, 0.42));

